import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // ============================================================================
  // 1. BUILD GEOMETRY & MATERIAL
  // ============================================================================
  const geometry = new THREE.PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  // Load the image texture asynchronously and apply it
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    material.colorNode = texture;
    material.needsUpdate = true;
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.position.set(0, 1, 0.06);
  plane.rotation.set(0, 0, 0);
  plane.scale.set(1, 1, 1);

  // ============================================================================
  // 2. CREATE TEXT CONTENT (HEADLINE)
  // ============================================================================
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new THREE.Group();

  for (const item of textItems) {
    if (item.role === 'headline') {
      const fontSize = item.typography?.fontSize ?? 39;
      const textMesh = ctx.fontAtlas.createText(String(item.text), {
        fontSize: fontSize,
        color: '#16161d',
        align: 'center',
      });
      textMesh.position.z = 0.01;
      textGroup.add(textMesh);
    }
  }

  // ============================================================================
  // 3. COMPOSE NODE
  // ============================================================================
  const node = new THREE.Group();
  node.add(plane);
  node.add(textGroup);

  // ============================================================================
  // 4. APPLY CINEMATIC PRIMITIVES
  // ============================================================================
  const primitiveRefs = [];

  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (primitive.name === 'parallax-scroll') {
        const ref = ctx.primitives['parallax-scroll'](node, primitive.params || {});
        primitiveRefs.push(ref);
      }
    }
  }

  // ============================================================================
  // 5. INTERACTION HANDLERS
  // ============================================================================
  const interactions = config.interactions ?? [];
  let currentTimeline = null;

  const handlers = {
    onHover: () => {
      if (currentTimeline) currentTimeline.kill();
      currentTimeline = gsap.timeline();

      // rise-in: +0.15 scene units, power3.out, 0.7s
      currentTimeline.to(
        plane.position,
        {
          y: plane.position.y + 0.15,
          duration: 0.7,
          ease: 'power3.out',
        },
        0
      );
    },

    onUnhover: () => {
      if (currentTimeline) currentTimeline.kill();
      currentTimeline = gsap.timeline();

      currentTimeline.to(
        plane.position,
        {
          y: 1,
          duration: 0.7,
          ease: 'power3.out',
        },
        0
      );
    },

    onClick: () => {
      if (currentTimeline) currentTimeline.kill();
      currentTimeline = gsap.timeline();

      // press-down: scale 0.97, 120ms, back.out
      currentTimeline.to(
        plane.scale,
        {
          x: 0.97,
          y: 0.97,
          duration: 0.12,
          ease: 'back.out',
        },
        0
      );

      // Emit navigation event
      ctx.emit('navigate', { to: 'hub-journal' });

      // Reset scale after press
      currentTimeline.to(
        plane.scale,
        {
          x: 1,
          y: 1,
          duration: 0.4,
          ease: 'power2.out',
        },
        0.12
      );
    },
  };

  // ============================================================================
  // 6. CLEANUP
  // ============================================================================
  node.userData.cleanup = () => {
    if (currentTimeline) {
      currentTimeline.kill();
      currentTimeline = null;
    }

    for (const ref of primitiveRefs) {
      if (ref && ref.cleanup) {
        ref.cleanup();
      }
    }

    geometry.dispose();
    material.dispose();
  };

  node.userData.handlers = handlers;

  return node;
}
